const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const LA_ROI = ee.Geometry.Rectangle([-118.8, 33.7, -117.9, 34.3]); // Approximate bounding box for Los Angeles
  const S5P_COLLECTION = 'COPERNICUS/S5P/OFFL/L3_NO2';
  const NO2_BAND = 'NO2_tropospheric_column_number_density';
  const SCALE = 1000; // Meters, appropriate for S5P data and region-wide average

  const years = [2018, 2019, 2021];
  const results = {};

  for (const year of years) {
    const startDate = `${year}-10-01`;
    const endDate = `${year}-10-23`;

    // 2. Data Acquisition & Check
    let collection = ee.ImageCollection(S5P_COLLECTION)
      .filterDate(startDate, endDate)
      .filterBounds(LA_ROI);

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      console.log(`Initial images for ${year}: 0`);
      console.log("C1"); // Empty Collection
      return;
    }

    // Apply quality and cloud mask, and filter negative NO2 values
    collection = collection
      .filter(ee.Filter.neq(NO2_BAND, null)) // Ensure band exists and is not null
      .filter(ee.Filter.gt(NO2_BAND, 0)) // Filter out negative NO2 values
      .filter(ee.Filter.gt('qa_value', 0.75)) // Filter by quality assurance value
      .filter(ee.Filter.lt('cloud_fraction', 0.3)); // Filter out high cloud cover

    const filteredSize = await collection.size().getInfo();
    if (filteredSize === 0) {
      console.log(`Images for ${year}: ${initialSize} (Val: 0)`);
      console.log("C2"); // No Valid Pixels after masking
      return;
    }

    // Take the mean of the NO2 band over the filtered collection
    const meanImage = collection.select(NO2_BAND).mean();

    // 3. Processing & Calculation
    // Get pixel count to check for C2 after mean and clipping
    const pixelCount = await meanImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: LA_ROI,
      scale: SCALE,
      maxPixels: 1e9
    }).get(NO2_BAND).getInfo();

    if (pixelCount === 0) {
      console.log(`Images for ${year}: ${initialSize} (Val: ${filteredSize})`);
      console.log("C2"); // No Valid Pixels after mean/reduceRegion
      return;
    }

    // Calculate the mean NO2 concentration for the region
    const no2Mean = await meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: LA_ROI,
      scale: SCALE,
      maxPixels: 1e9
    }).get(NO2_BAND).getInfo();

    if (no2Mean === null || isNaN(no2Mean)) {
      console.log(`Images for ${year}: ${initialSize} (Val: ${filteredSize}), Pixels: ${pixelCount}`);
      console.log("C3"); // Calculation Failure
      return;
    }

    results[year] = {
      mean: no2Mean,
      pixels: pixelCount,
      initialImages: initialSize,
      validImages: filteredSize
    };

    console.log(`${year} Images: ${results[year].initialImages} (Val: ${results[year].validImages}), Pixels: ${results[year].pixels}, Mean NO2: ${results[year].mean.toFixed(6)}`);
  }

  // 5. Validation & Final Answer
  const no2_2021 = results[2021].mean;
  const no2_2019 = results[2019].mean;
  const no2_2018 = results[2018].mean;

  // Question: 'Was the concentration of tropospheric nitrogen dioxide (NO2) over Los Angeles lower between October 1-23, 2021 compared to the same period in 2019 and 2018?'
  // This means 2021 NO2 < 2019 NO2 AND 2021 NO2 < 2018 NO2
  const isLower = no2_2021 < no2_2019 && no2_2021 < no2_2018;

  if (isLower) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
